<span class="line"><span style="color:#C678DD;">        string</span><span style="color:#E06C75;"> interned</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> string</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Intern</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">temp</span><span style="color:#ABB2BF;">);</span></span>
