<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#C678DD;"> string</span><span style="color:#ABB2BF;">? </span><span style="color:#E06C75;">Nickname</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;">// 可空引用类型</span></span>
